from __future__ import annotations
import json, sys
from pathlib import Path

VERSION='18.327'
MARK='FUTBR_UNEMPLOYED_TURBO_18327'

def once(source, old, new, label):
    count=source.count(old)
    if count!=1:
        raise RuntimeError(f'{label}: expected one occurrence, found {count}')
    return source.replace(old,new,1)

def main():
    if len(sys.argv)!=2:
        raise SystemExit('usage: optimize_unemployed_turbo_18327.py <project-dir>')
    root=Path(sys.argv[1]).resolve()
    target=root/'src'/'index.html'
    html=target.read_text(encoding='utf-8')
    if MARK in html:
        print(json.dumps({'ok':True,'version':VERSION,'alreadyInstalled':True}))
        return

    # Full engine was being selected for the former human club as well as
    # top domestic and international fixtures, even after the manager was fired.
    # Apply only to AI club fixtures, never an active national-team career.
    html=once(html,
        "if(!f)return true;\n    // A partida do clube do usuario nunca perde o motor detalhado.",
        "if(!f)return true;\n    // 18.327: a manager without a club is not controlling any club fixture.\n"
        "    // Keep score, scorers, assists and titles via the existing Turbo match pipeline.\n"
        "    if(s?.userEmployed===false&&!s?.v640National?.userTeam)return false;\n"
        "    // A partida do clube do usuario nunca perde o motor detalhado.",
        'force AI club Turbo while unemployed')

    # Previously this loop used the old, slow 'day' Worker route. Use the same
    # one-day low-memory Worker route as the manual Advance Jornada button.
    begin=html.index('async function v89RunJobWait(){')
    end=html.index('const v89BaseCareerPage=careerPage;',begin)
    block=html[begin:end]
    block=once(block,"await v53StartSimulation('day');",
        "await v53StartSimulation('dayfast');",'job wait fast Worker mode')
    html=html[:begin]+block+html[end:]

    # Important: coach offers were generated by this UI post-round hook for
    # 'day', not 'dayfast'. Without extending it, a Turbo job search could run
    # the entire season without producing a single proposal.
    html=once(html,
        "if((mode==='day'||mode==='vacation')&&state){if(mode==='day')v636AfterRound(state,before);",
        "if((mode==='day'||mode==='dayfast'||mode==='vacation')&&state){if(mode==='day'||mode==='dayfast')v636AfterRound(state,before);",
        'regenerate coach offers after every Turbo jornada')

    status="""window.GestorFC.unemployedTurbo18327={
 version:'18.327',mode:'dayfast',allAIClubMatchesTurbo:true,
 nationalCoachUsesOriginalEngine:true,offerCheckEachRound:true,
 status:()=>({enabled:!!(state?.userEmployed===false&&!state?.v640National?.userTeam),
 waiting:!!v89JobWait?.active,day:Number(state?.day)||0,year:Number(state?.year)||0,
 full:Number(state?.v33HybridStats?.full)||0,turbo:Number(state?.v33HybridStats?.turbo)||0})
};\n/* FUTBR_UNEMPLOYED_TURBO_18327 */\n"""
    anchor="window.GestorFC.version='18.155';window.GestorFC.visualVersion='18.155';"
    html=once(html,anchor,status+anchor,'runtime audit marker in career scope')

    if "await v53StartSimulation('day');" in html[html.index('async function v89RunJobWait(){'):html.index('const v89BaseCareerPage=careerPage;')]:
        raise RuntimeError('Old job-wait mode still present')
    target.write_text(html,encoding='utf-8')
    report={'ok':True,'version':VERSION,'jobWaitWorkerMode':'dayfast',
        'unemployedClubFixturesTurbo':True,'formerUserClubTurbo':True,
        'internationalClubFixturesTurbo':True,'nationalCareerUnaffected':True,
        'coachOfferEvaluationPerDay':True,'savesAndMatchStats':'existing engines unchanged'}
    (root/'unemployed-turbo-18327-install.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps(report,ensure_ascii=False))

if __name__=='__main__':
    main()
